  int lvl = (int)me->query_skill("taiji-shengong", 1);
  int t = 1, j;
  if (lvl <= 100)
    for (j = 1; j < lvl / 10; j++)
      t *= 2;

  if (me->query("gender") == "无性" && lvl > 49)
    return notify_fail("你无根无性，阴阳不调，难以领会高深的太极神功。\n");

  if (((userp(me)||me->query("pocket_avatar")) ? 0 : (me->query("class") == "bonze")))
