用。凿户牖以为室，当其无，有室之用。”就是说，碗只因为中间
是空的，才有盛饭的功用，倘若它是实心的一块瓷土，还能装甚么
饭？建造房屋，开设门窗，只因为有了四壁中间的空隙，房子才能
住人。倘若房屋是实心的，倘若门窗不是有空，砖头木材四四方方
的砌上这么一大堆，那就一点用处也没有了。全真派最上乘的武功，
要旨就在“空、柔”二字，那就是所谓“大成若缺，其用不弊。大
盈若冲，其用不穷”。空明拳乃是天下至柔的武功，能增强招架。

	学习要求：
		内力100
HELP
  );
  return 1;
}

kungfu/skill/force.h:
// force.h

varargs int valid_public(object me,mixed comb)
{
	mapping skl = me->query_skills();
	string *sk;
	int i;
	// __FILE__ inside this include identifies force.h, not the calling skill.
	string skl_name = explode(base_name(this_object()), "/")[<1];
  string* can_skill;

  can_skill = ({ "shenzhao-jing" , "taixuan-gong" });
  can_skill += ({ skl_name });
  if (stringp(comb)) can_skill += ({comb});
  if (arrayp(comb)) can_skill += comb;

	if (!mapp(skl)) return 1;
	if (SCBORN_D->valid_learn(me,skl_name)) return 1;
	sk = keys(skl);
	i = sizeof(sk);
	while (i--)
	{
		if (SKILL_D(sk[i])->valid_enable("force"))
			if ( member_array(sk[i],can_skill) == -1 )
		     	     if (!SCBORN_D->valid_learn(me,sk[i])) 
				return notify_fail("你不散掉"+to_chinese(sk[i])
					+"，如何能修习"+to_chinese(skl_name)+"。\n");
	}
	return 1;
}

