		寒冰绵掌60级
		基本轻功150级
		内力200
HELP
  );
  return 1;
}

kungfu/skill/force/recover.lpc:
// recover.c
// Last Modified by winder on Mar. 10 2000

#include <ansi.h>
//inherit SSERVER;

int exert(object me, object target) {
  int n, q;

  if (me != target)
    return notify_fail("你只能用内功调匀自己的气息。\n");

  if ((int)me->query("neili") < 20)
    return notify_fail("你的内力不够。\n");

  q = (int)me->query("eff_qi") - (int)me->query("qi");
  if (q < 10)
    return notify_fail("你现在气力充沛。\n");
  if(me->is_fighting()) {
    int cap=me->query("max_qi")/10;if(cap<50)cap=50;if(cap>300)cap=300;
    if(me->query_temp("pocket_recover_at")+15>time())return notify_fail("战斗运功恢复每15秒可用一次。\n");
    if(q>cap)q=cap;
  }
  n = 100 * q / me->query_skill("force");
  if (n < 20)
    n = 20;
  if ((int)me->query("neili") < n) {
    q = q * (int)me->query("neili") / n;
    n = (int)me->query("neili");
  }

  if(me->is_fighting())me->set_temp("pocket_recover_at",time());
  me->add("neili", -n);
  me->receive_heal("qi", q);

  message_combatd("$N深深吸了几口气，脸色看起来好多了。\n", me);

  if (me->is_fighting()) me->start_busy(1);

  return 1;
}
int help(object me) {
  write(WHT "\n基本内功之调匀气血：" NOR "\n");
  write(@HELP

	使用功效：
		恢复气血自己损失

	出手要求：
		基本内功
		内力20
HELP
  );
  return 1;
}

