string ask_ling() {
  mapping fam;
  object ob, me = this_player();

  if (!(fam = me->query("family")) || fam["family_name"] != "全真教")
    return RANK_D->query_respect(me) + "与本教毫无瓜葛，不知此话从何谈起？";

  // Mobile progression: only three learnable core categories gate the permit.
  {
    string *missing = ({});
    string *attacks = ({"chunyang-quan", "haotian-zhang", "quanzhen-jian", "duanyun-bian"});
    int best = 0;
    if (me->query_skill("force", 1) < 30)
      missing += ({ sprintf("基本内功：当前%d级，需30级，还差%d级", me->query_skill("force", 1), 30-me->query_skill("force", 1)) });
    if (me->query_skill("dodge", 1) < 30)
      missing += ({ sprintf("基本轻功：当前%d级，需30级，还差%d级", me->query_skill("dodge", 1), 30-me->query_skill("dodge", 1)) });
    foreach (string attack in attacks)
      if (me->query_skill(attack, 1) > best) best = me->query_skill(attack, 1);
    if (best < 30)
      missing += ({ sprintf("全真攻击武学任选一门（纯阳拳、昊天掌、全真剑法、断云鞭）：当前最高%d级，需30级，还差%d级", best, 30-best) });
    if (sizeof(missing))
      return RANK_D->query_respect(me) + "，领取全真令只需基本内功30级、基本轻功30级，以及一门全真攻击武学30级。\n尚未达标：\n" + implode(missing, "\n") + "\n其他基本功、兵器和知识技能不作要求。请向现任师父补足以上核心武学后再来。";
  }

