		command("say 怎麽样，你拿我的推荐信去拜师了吗 ?");
		return 0;
	}

	if ((obj->query("id") == "quanzhen ling") && ob_fam["family_name"] == "全真教" && ob_fam["generation"] == my_fam["generation"] + 1 && !ob->query_temp("have_letter"))
	{
		ob->set_temp("fight_ok", 1);
        ob->set("pocket_faction_task",(["stage":"ready_challenge","teacher":base_name(me),"teacher_name":me->name(),"room":base_name(environment(me)),"message":"全真令已交付；现在与现任师父切磋，获胜后领取推荐信"]));
