int accept_fight(object ob)
{
	object me = this_object();

	if (!ob->query_temp("fight_ok"))
		return 0;

	remove_call_out("checking");
	call_out("checking", 1, me, ob);
	ob->delete_temp("fight_ok");

	return 1;
}

int checking(object me, object ob)
{
	object obj;
	int my_max_qi, his_max_qi;

	my_max_qi = me->query("max_qi");
	his_max_qi = ob->query("max_qi");

    if(ob->query_temp("have_letter") && present("quanzhen xin2",ob)) return 1;
	if (me->is_fighting())
	{
		call_out("checking", 2, me, ob);
		return 1;
	}

	if (!present(ob, environment()))
		return 1;

	if (me->query_temp("pocket_spar_lost_to")==ob || ((int)me->query("qi")*100 / my_max_qi)<=50)
	{
		command("say 青出於蓝胜於蓝，不愧是全真门下弟子！恭喜你了！\n");
		message_vision("$N交给$n一封推荐信。\n", me, ob);
        me->delete_temp("pocket_spar_lost_to");
        ob->set("pocket_faction_task",(["generation":me->query("family/generation"),"stage":"letter","letter":"xin2","teacher":base_name(me),"teacher_name":me->name(),"room":base_name(environment(me)),"message":"已赢得推荐挑战；请把推荐信交给上一代师父，再行拜师礼"]));
		ob->set_temp("have_letter", 1);
		obj = new ("/d/quanzhen/obj/tuijianxin-2");
