  if (interactive(me) && me->query_condition("wait_xx_task"))
    return "老仙现在心情还好，不用你来为我分忧。";
  if (query("di_count") < 1)
    return "老仙现在心情还好，再来烦我就别怪老仙心情不好了。";

  ob = new(__DIR__ "obj/di");
