    destruct(ob);
    ob = temp;
    owner = environment(ob);
    if (owner == me)
      return ob->query("name") + "不就在你手中吗？";
    if (objectp(owner) && owner != this_object()) {
      if (!owner->is_character())
        return "你来晚了，" + ob->query("name") + "现在不在我手中。";
