int do_xunshan() {
  int exp, pot, score, num, times;

  object me = this_player();
  if (me->query_temp("xunshan")) {
    if (!me->query_temp("xunshan/chaoyang")) {
      message_vision("$N对着$n说：你朝阳峰没去看看？这算巡的什么山？\n", this_object(), me);
      return 1;
    }
    if (!me->query_temp("xunshan/lianhua")) {
      message_vision("$N对着$n说：你莲花峰没去看看？这算巡的什么山？\n", this_object(), me);
      return 1;
    }
    if (!me->query_temp("xunshan/yuntai")) {
      message_vision("$N对着$n说：你云台峰没去看看？这算巡的什么山？\n", this_object(), me);
      return 1;
    }
    if (!me->query_temp("xunshan/sheshen")) {
      message_vision("$N对着$n说：你怎么没去舍身崖？这算巡的什么山？\n", this_object(), me);
      return 1;
    }
    if (!me->query_temp("xunshan/siguo")) {
      message_vision("$N对着$n说：你到了思过崖去了？这算巡的什么山？\n", this_object(), me);
      return 1;
    }
    if (!me->query_temp("xunshan/yunu")) {
      message_vision("$N对着$n说：你到玉女峰后面华山小筑去看过了？这算巡的什么山？\n", this_object(), me);
      return 1;
    }
    message_vision("$N对着$n说：不错，辛苦了。你这就去休息去吧。\n", this_object(), me);
    me->delete_temp("xunshan");

    num = (int)me->query("perform/number") + 1;
    if (num < 4) times = num;
    else times = 4;

    exp = random(100);
    pot = random(30);
    score = random(10) + 10 * times;

    me->add("combat_exp", exp);
    me->add("potential", pot);
    me->add("family/fealty", score);
    tell_object(me, HIW "好！任务完成,你被奖励了：\n" +
      chinese_number(exp) + "点实战经验\n" +
      chinese_number(pot) + "点潜能\n" +
      chinese_number(score) + "点忠诚度\n");



    return 1;
  } else {
    if (query("xunshan") < 1) {
      message_vision("$N对着$n说：今天已经有人巡山去了。你明天再来吧。\n", this_object(), me);
      return 1;
    }
    if (0) {
      message_vision("$N对着$n大喝一声：本派弟子才能巡山。你是哪来的奸细？休怪我剑下不留情！\n", this_object(), me);
      // this_object()->kill_ob(me);
      return 1;
    } else {
      add("xunshan", -1);
      message_vision("$N对着$n说：本派弟子例当巡山。你，很好，很好！这就去吧。\n", this_object(), me);
      me->set_temp("xunshan/start", 1);
      me->set_temp("xunshan/time", time());
      return 1;
    }
  }
}

cmds/skill/apprentice.lpc:
// apprentice.c
inherit F_CLEAN_UP;

#include <ansi.h>



int main(object me, string arg) {
  object ob, old_app;
  mapping family /*, skills*/;
  int /*i,*/ fealty;
  //	string *skname;
  object room;
  object feng;
  int flag, transfer;

  seteuid(getuid());
  if (me->is_busy()) return notify_fail("你现在正忙着呢。\n");
  if (!arg) return notify_fail("指令格式：apprentice | bai [cancel]|<对象>\n");
  if (arg == "cancel") {
    old_app = me->query_temp("pending/apprentice");
    if (!objectp(old_app))
      return notify_fail("你现在并无拜任何人为师的意思。\n");
    write("你改变主意不想拜" + old_app->name() + "为师了。\n");
    tell_object(old_app, me->name() + "改变主意不想拜你为师了。\n");
    me->delete_temp("pending/apprentice");
    return 1;
  }
  if (!(ob = present(arg, environment(me))) || !ob->is_character())
    return notify_fail("你想拜谁为师？\n");
  if (!living(ob) || ob->query_temp("noliving"))
    return notify_fail("你必须先把" + ob->name() + "弄醒。\n");
  if (ob == me)
    return notify_fail("拜自己为师？好主意....不过没有用。\n");
  if (me->is_apprentice_of(ob)) {
    me->set("pocket_master_source",base_name(ob));
    message_vision("$N恭恭敬敬地向$n磕头请安，叫道：「师父！」\n", me, ob);
    return 1;
  }
  if (!mapp(ob->query("family")))
    return notify_fail(ob->name() + "既不属於任何门派，也没有开山立派，不能拜师。\n");

  transfer="/adm/daemons/pocketexpansion"->transfer(me,ob);
  if(transfer) return 1;

  // If the target is willing to recruit us already, we do it.
  if ((object)ob->query_temp("pending/recruit") == me) {
    if (me->query("detach/" + ob->query("family/family_name")) > 0) {
      ob->delete_temp("pending/recruit");
      message_vision(
        "$N看了看$n，摇了摇头道：「你当年既然离开了" + ob->query("family/family_name") + "，今天又何必回来？」\n",
        ob,
        me
      );
      return 1;
    }

    fealty = (int)(me->query("family/fealty"));
    me->set_temp("fealty_temp", fealty);
    if ((me->query("family")) && (string)me->query("family/family_name") !=
      (string)ob->query("family/family_name")) {
      if (me->query("combat_exp") > 10000) {
        message_vision("$N经验太高了，不能改投$n门下！！\n\n", me, ob);
        return 0;
      }
      message_vision("$N决定背叛师门，改投入$n门下！！\n\n$N跪了下来向$n恭恭敬敬地磕了四个响头，叫道：「师父！」\n\n", me, ob);
      me->add("detach/" + me->query("family/family_name"), 1);
      me->set("family/fealty", 0);
      me->set_temp("fealty_temp", 0);
      me->add("betrayer", 1);
    } else
      message_vision("$N决定拜$n为师。\n\n$N跪了下来向$n恭恭敬敬地磕了四个响头，叫道：「师父！」\n\n", me, ob);
    if ((string)me->query("family/master_id") == "feng qingyang") {
      room = find_object("/d/huashan/xiaofang");
      if (!objectp(room)) room = load_object("/d/huashan/xiaofang");
      feng = present("feng qingyang", room);
      if (!objectp(feng)) {
        feng = new("/kungfu/class/huashan/feng");
        flag = 1;
      }
      feng->delete("students/" + me->query("id"));
      feng->set("no_accept/" + me->query("id"), 1);
      feng->save_data();
      if (flag == 1) destruct(feng);
    }
    ob->recruit_apprentice(me);
    me->set("pocket_master_source",base_name(ob));
    ob->delete_temp("pending/recruit");

    tell_object(ob, "恭喜你新收了一名弟子！\n");
    family = me->query("family");
    printf(
      "恭喜您成为%s的第%s代弟子。\n",
      me->query("family/family_name"),
      chinese_number(me->query("family/generation"))
    );
    fealty = (int)(me->query_temp("fealty_temp"));
    me->set("family/fealty", fealty);
    me->delete_temp("fealty_temp");
    //me->set_temp("faint",200);
    return 1;
  } else {
    fealty = (int)(me->query("family/fealty"));
    me->set_temp("fealty_temp", fealty);
    old_app = me->query_temp("pending/apprentice");
    if (ob == old_app && userp(ob))
      return notify_fail("你想拜" + ob->name() + "为师，但是对方还没有答应。\n");
    else if (objectp(old_app) && old_app != ob) {
      write("你改变主意不想拜" + old_app->name() + "为师了。\n");
      tell_object(old_app, me->name() + "改变主意不想拜你为师了。\n");
    }

    message_vision("$N想要拜$n为师。\n", me, ob);
    me->set_temp("pending/apprentice", ob);
    if (userp(ob)) {
