			pfarg = "perform/" + arg;
			if( me->query(pfarg,1)<1 )
				return notify_fail("你必须先向贵派掌门请教如何运用这门外"+arg+"。\n");
		}		
	}*/
  if (!stringp(me->query_skill_mapped("force")))
