            message_combatd(msg, me, target);
            return 0;
          }
          me->delete_temp("murong/xingyi");
        } else {
          result = 1;
          msg = HIG "$N真气流转不顺，一时无法使出「星移」！\n" NOR;
          message_combatd(msg, me, target);
        }
        return result;
      }
    }
    me->start_busy(random(2) + 1);
    me->delete_temp("murong/xingyi");
    return 1;
  }
}
int help(object me) {
  write(@HELP
指令格式：perfrom | yong [<武功种类>.]<招式名称> [<施用对象>]
          perform | yong 招式1 [<对象1>] and 招式2 [<对象2>]

    如果你所学的外功（拳脚、剑法、刀法....）有一些特殊的攻击方
式或招式，可以用这个指令来使用，你必须先用 enable 指令指定你使
用的武功，不指定武功种类时，空手的外功是指你的拳脚功夫，使用武
器时则是兵刃的武功。空手外功的施展，必须先准备好 （prepare）你
的技能。有的特别的外功可以激发相应技能为parry来施展。

    若是你的外功中有种类不同，但是招式名称相同的，或者不属於拳
脚跟武器技能的武功(如轻功)，可以用 <武功>.<招式>  的方式指定，
如：

    perform sword.chan
    perform sword.chan and sword.lian

    换句话说，只要是 enable 中的武功有特殊招式的，都可以用这个
指令使用。很多武功的特殊攻击法都非常凌厉，一旦使用，将招致对方
的拼死反击，就是说，被攻击方将自动开始ｋｉｌｌ你。所以要谨慎使
用哦:)。

如果你精通左右互搏，可以同时使用两个招式攻击同一对手或则分别
攻击两人。左右互搏修炼的越是精深，则成功率越高。

HELP
  );
  return 1;
}

cmds/skill/exercise.lpc:
// exercise.c
inherit F_CLEAN_UP;

#include <skill.h>



int exercising(object me);
//int halt_exercise(object me, object who, string why);
int halt_exercise(object me);

int main(object me, string arg) {
  int exercise_cost;
  object where;

  seteuid(getuid());
  where = environment(me);

  if (where->query("pigging"))
    return notify_fail("你还是专心拱猪吧！\n");

  if (where->is_chat_room() && where->query("no_fight"))
    return notify_fail("这里禁止打坐。\n");

  if (me->is_busy() || me->query_temp("pending/exercising"))
    return notify_fail("你现在正忙着呢。\n");

  if (me->is_fighting())
    return notify_fail("战斗中不能练内功，会走火入魔。\n");

  if (!stringp(me->query_skill_mapped("force")))
    return notify_fail("你必须先用 enable 选择你要用的内功心法。\n");

  if (!arg || !sscanf(arg, "%d", exercise_cost))
    return notify_fail("你要花多少气练功？\n");
  if (exercise_cost < 10)
    return notify_fail("你的内功还没有达到那个境界！\n");

  if ((int)me->query("qi") < exercise_cost)
    return notify_fail("你现在的气太少了，无法产生内息运行全身经脉。\n");

  if ((int)me->query("jing") * 100 / (int)me->query("max_jing") < 70)
    return notify_fail("你现在精不够，无法控制内息的流动！\n");

  write("你坐下来运气用功，一股内息开始在体内流动。\n");

  me->set_temp("pending/exercise", 1);
  me->set_temp("exercise_cost", exercise_cost);
  message_vision("$N盘膝坐下，开始修炼内力。\n", me);
  me->start_busy((: exercising :), (: halt_exercise :));

  return 1;
}

int exercising(object me) {
  int exercise_cost = (int)me->query_temp("exercise_cost");
  int neili_gain = 1 + (int)me->query_skill("force") / 10;
  int max_neili_gain = (int)random(me->query("max_neili") / 500);

  int taixuan;
  object where = environment(me);
  if (exercise_cost < 1)
    return 0;
  me->add("neili", neili_gain);
  me->set_temp("exercise_cost", exercise_cost -= neili_gain);
  // 灵鹫玄冰室
  if (where->query("xuanbing"))
    me->add("qi", (int)neili_gain / 3);
  // 太玄功
  if ((int)me->query_skill("taixuan-gong", 1)) {
    taixuan = (int)me->query_skill("taixuan-gong", 1);
    if (taixuan > 10)
      me->add("qi", (int)neili_gain * taixuan / 400);
  }
  // 神照经
  if ((int)me->query_skill("shenzhao-jing", 1)) {
    taixuan = (int)me->query_skill("shenzhao-jing", 1);
    if (taixuan > 10)
      me->add("qi", (int)neili_gain * taixuan / 400);
  }

  if (living(me) && !me->query_temp("noliving"))
    me->add("qi", -neili_gain);

  if (exercise_cost > 0)
    return 1;

  me->set_temp("pending/exercise", 0);
  message_vision("$N运功完毕，深深吸了口气，站了起来。\n", me);
  if ((int)me->query("neili") < (int)me->query("max_neili") * 2)
    return 0;
  else {
    if ((int)me->query("max_neili") >= (int)me->query_skill("force") * 10) {
      write("你的内力修为似乎已经达到了瓶颈。\n");
      me->set("neili", (int)me->query("max_neili"));
      return 0;
    } else {
      if (max_neili_gain > 2) max_neili_gain = 2;
      max_neili_gain=(1+max_neili_gain)*(me->query("pocket_training_boost")?3:1);
      if(me->query("max_neili")+max_neili_gain>me->query_skill("force")*10)max_neili_gain=me->query_skill("force")*10-me->query("max_neili");
      if(max_neili_gain>0)me->add("max_neili",max_neili_gain);
      "/adm/daemons/pocketgrowth"->sync(me);
      me->set("neili", (int)me->query("max_neili"));
      write("你的内力增加了！！\n");
      return 0;
    }
  }
}

int halt_exercise(object me) {
  if ((int)me->query("neili") > (int)me->query("max_neili") * 2)
    me->set("neili", (int)me->query("max_neili") * 2);
  me->set_temp("pending/exercise", 0);
  return 1;
}

int help(object me) {
  write(@HELP
指令格式 : exercise | dazuo <耗费「气」的量>

    运气练功，控制体内的气在各经脉间流动，藉以训练人体肌肉骨
骼的耐力、爆发力，并且用内力的形式将能量储备下来。
    耗费气的量必须不小于１０。

HELP
  );
  return 1;
}

cmds/skill/learn.lpc:
// /cmds/skill/learn.c

// Modified by Constant Jan 11 2001

inherit F_CLEAN_UP;

#include <skill.h>
#include <ansi.h>


string *reject_msg = ({
  "说道：您太客气了，这怎么敢当？\n",
  "像是受宠若惊一样，说道：请教？这怎么敢当？\n",
  "笑着说道：您见笑了，我这点雕虫小技怎够资格「指点」您什么？\n",
});

void create() { seteuid(getuid()); }

int main(object me, string arg) {
  string skill, teacher /*, master*/, skill_name;
  object ob;
  int master_skill, my_skill, jing_cost, times, pertimes;
  int improve_points, target;
  mixed flag;
  int i, forced;

  if (me->is_busy())
    return notify_fail("你现在正忙着呢。\n");
  if (environment(me)->is_chat_room())
    return notify_fail("这里禁止练功。\n");
  if (!arg || (sscanf(arg, "%s %s %d %d", teacher, skill, times, target) != 4 &&
      sscanf(arg, "%s %s %d", teacher, skill, times) != 3))
    return notify_fail("指令格式：learn|xue <某人> <技能> <次数>\n");
  if (times < 1 || times > 100)
    return notify_fail("学习次数最少一次，最多也不能超过一百次。\n");
  if (me->is_fighting())
    return notify_fail("临阵磨枪？来不及啦。\n");
  if (!(ob = present(teacher, environment(me))) || !ob->is_character())
    return notify_fail("你要向谁求教？\n");
  if (!living(ob) || ob->query_temp("noliving"))
    return notify_fail("嗯....你得先把" + ob->name() + "弄醒再说。\n");

  forced="/adm/daemons/pocketexpansion"->coerced(me,ob);
  notify_fail(ob->name() + reject_msg[random(sizeof(reject_msg))]);
  if (!forced && !me->is_apprentice_of(ob) && !(ob->recognize_apprentice(me, skill))) {
    return 0;
  }
  if (!master_skill = ob->query_skill(skill, 1))
    return notify_fail("这项技能你恐怕必须找别人学了。\n");

  if (!forced && stringp(flag = ob->query("no_teach/" + skill))) {
    message_vision(CYN "$N" CYN "摇摇头，说道：" + flag + "\n" NOR, ob);
    return 1;
  } else if (!forced && intp(flag) && flag) {
    if (flag != 1)
      // show the messaeg if the result was not -1
      write(CYN + ob->name() + CYN "说道：对不起，" +
        to_chinese(skill) + "可不能随便传授。\n" NOR);
    return 1;
  }

  notify_fail(ob->name() + "不愿意教你这项技能。\n");
  if (!forced && ob->prevent_learn(me, skill))
    return 0;
  my_skill = me->query_skill(skill, 1);
  if (target && (target<=my_skill || target>master_skill))
    return notify_fail("目标等级须高于当前等级且不超过师父实际教学上限。\n");
  if (my_skill >= master_skill)
    return notify_fail("这项技能你的程度已经不输你师父了。\n");
  notify_fail("依你目前的能力，没有办法学习这种技能。\n");
  if (!forced && !SKILL_D(skill)->valid_learn(me))
    return 0;

  jing_cost = 150 / (int)me->query("int");
  if (!my_skill) {
    jing_cost *= 2;
    me->set_skill(skill, 0);
  }

  if ((me->query("potential") - me->query("learned_points")) < times)
    return notify_fail("你的潜能不够学习这么多次了。\n");
  printf(
    HIC "你向%s请教了" + chinese_number(times) + "句有关「%s」的疑问。\n" NOR,
    ob->name(),
    to_chinese(skill)
  );
  if (!forced && ob->query("env/no_teach"))
    return notify_fail("但是" + ob->name() + "现在并不准备回答你的问题。\n");
  tell_object(ob, sprintf("%s向你请教有关「%s」的问题。\n",
    me->name(), to_chinese(skill)));
  if (userp(ob))
    if ((int)ob->query("jing") > jing_cost * times / 5 + 1) {
      ob->receive_damage("jing", jing_cost / 5 + 1);
    } else {
      write("但是" + ob->name() + "显然太累了，没有办法教你什么。\n");
      tell_object(ob, "但是你太累了，没有办法教" + me->name() + "。\n");
      return 1;
    }
  if ((string)SKILL_D(skill)->type() == "martial" &&
    my_skill * my_skill * my_skill / 10 > (int)me->query("combat_exp")) {
    return notify_fail("也许是缺乏实战经验，你对" + ob->name() + "的回答总是无法领会。\n");
  }
  if (!me->query("pocket_jing_locked") && !me->query("env/auto_regenerate") &&
    me->query("jing") < jing_cost * times)
    return notify_fail("你今天太累了，结果什么也没有学到。\n");
  // Touch automation uses a bounded target, but every lesson still invokes the
  // original cost, prerequisites and random skill improvement. Never overshoot.
  if (target) {
    for (pertimes=0; pertimes<times && me->query_skill(skill,1)<target; pertimes++) {
      if (me->query("jing")<jing_cost) break;
      me->receive_damage("jing",jing_cost);
      me->add("learned_points",1);
      improve_points=(me->query_int()+me->query("int"))/2;
      improve_points+=SKILL_D(skill)->learn_bonus()||10;
      improve_points/=me->query("betrayer")+1;
      if(improve_points<15) improve_points=15;
      me->set_temp("pocket_lesson_target",target);me->improve_skill(skill,random(improve_points));me->delete_temp("pocket_lesson_target");
    }
    if(!pertimes) return notify_fail("你今天太累了，结果什么也没有学到。\n");
    printf("你听了%s的指导，学习了%d次，似乎有些心得。\n",ob->name(),pertimes);
    return 1;
  }
  //	if( (int)me->query("jing") > jing_cost * times )
  for (pertimes = 0; pertimes < times; pertimes++) {
    if ((int)me->query("jing") < jing_cost) {
      if (me->query("env/auto_regenerate") &&
        SKILL_D("force/regenerate")->exert(me, me)) {
        // try to regenerate & learn again
        write("你觉得精神好了一些，继续进行学习。\n");
        pertimes--;
        continue;
      } else {
        //             me->set("jing", 0);
        break;
      }
    }
    me->receive_damage("jing", jing_cost);
    me->add("learned_points", 1);

  }
  if (pertimes > 0) {
    for (i = 0; i < pertimes; i++) {
      // 学习速度 = 后天悟性加上先天悟性的和的一半，加武功学习补偿。
      // 未定义学习补偿的技能，默认学习补偿为10。
      improve_points = (me->query_int() + me->query("int")) / 2;
      if (SKILL_D(skill)->learn_bonus())
        improve_points += SKILL_D(skill)->learn_bonus();
      else improve_points += 10;
      // 调整向师父学习技能的速度，加重对叛师的惩罚。
      improve_points = improve_points / (me->query("betrayer") + 1);
      if (improve_points < 15) improve_points = 15;
      improve_points = random(improve_points);
      // 对师傅传授产生误解的比率。== 0时候误解。
      //				if(random(SKILL_D(skill)->success()) )
      me->set_temp("pocket_lesson_target",master_skill);me->improve_skill(skill, improve_points);me->delete_temp("pocket_lesson_target");
    }
    if (skill_name = SKILL_D(skill)->query_skill_name(my_skill))
      printf("你听了%s的指导，对「%s」这一招似乎有些心得。\n", ob->name(), skill_name);
    else
      printf("你听了%s的指导，似乎有些心得。\n", ob->name());
    if (pertimes < times)
      return notify_fail("但是你今天太累了，学习了" + chinese_number(pertimes) + "次以后只好先停下来。\n");
  } else
    return notify_fail("你今天太累了，结果什么也没有学到。\n");
  return 1;
}

int help(object me) {
  write(@HELP
指令格式 : learn|xue <某人> <技能> <次数>

    这个指令可以让你向别人请教有关某一种技能的疑难问题，当然，你
请教的对象在这项技能上的造诣必须比你高，而你经由这种方式学习得来
的技能也不可能高于你所请教的人，然而因为这种学习方式相当於一种「
经验的传承」，因此学习可以说是熟悉一种新技能最快的方法。

    通常，一个人刚学到一种新技能是不会有什么疑难问题的，而是经由
实际上的应用中遭遇问题，这些问题对於学习一种新技能的过程是很重要
的，尤其是各种作为其他技能基础的基本技能，更需要经由「发现问题—
解决问题」的过程才能得到较好的效果因此我们将这种发现问题的过程用
「潜能」的观念表示，一个人能够自己发现某些问题，表示他（她）有解
决这项问题的潜能，当你具有这样的潜能时就可以利用这个指令来向其他
人请教，而获得进步。

(PS. 潜能还有其他更广义的定义，这里只是其中之一 )

    此外学习也需要消耗一些精力，而消耗的精力跟你自己、与你学习对
象的悟性有关。

    至于如何知道你能从对方学到什么技能，如果对方是你的师父，可以
用 skills 指令直接查看，如果不是你的师父，那么通常会有其他的提示，
你只好自己想办法。

其他相关指令 : apprentice, practice, skills, study
HELP
  );
  return 1;
}

cmds/std/kill.lpc:
// kill.c
inherit F_CLEAN_UP;

#include <ansi.h>



int main(object me, string arg) {
  object obj, hitter;
  string /**killer,*/ callname;
  seteuid(getuid());
  if (environment(me)->query("no_ansuan"))
    return notify_fail("这里禁止战斗。\n");
  if (environment(me)->query("no_fight"))
    return notify_fail("这里不准战斗。\n");
  if (me->is_busy())
    return notify_fail("你上一个动作还没有完成！\n");
  if (!arg)
    return notify_fail("你想杀谁？\n");
  if (!objectp(obj = present(arg, environment(me))))
    return notify_fail("这里没有这个人。\n");
  if (!obj->is_character() || obj->is_corpse())
    return notify_fail("看清楚一点，那并不是活物。\n");
  //	if (userp(me)&& obj->query("owner") && me->query("id") != obj->query("owner"))
  //    return notify_fail("不是你要抓的人，凑什么热闹！\n");
  //增加一个yinshi任务的限制条件		
  if (obj->query("no_kill") || (obj->query("yinshi") && obj->query("ask_time") <= 2))
    return notify_fail("你真黑，居然下得了这个毒手！\n");

  if (objectp(hitter = obj->query_temp("last_damage_from"))) {
    if (hitter->query("id") != me->query("id")) {
      if ((obj->query("name") ==
        me->query("family_quest/betrayer/name") ||
        obj->query("name") ==
        me->query("family_quest/thief/name") ||
        obj->query("name") ==
        me->query("quest/shan/quest") ||
        obj->query("name") ==
        me->query("quest/helian/quest")) &&
        (!living(obj) || obj->query_temp("noliving") ||
          obj->query("qi") < obj->query("max_qi") / 2))
        return notify_fail("不是你打伤的，你不能杀了来完成任务。\n");
      else
        message_vision(
          "\n$N对着$n得意地笑道：「" + obj->query("name") + "！今日活该你倒霉，欺侮你身上有伤，这个便宜我就不客气了！」\n\n",
          me,
          obj
        );
    }
  }

  if (me->query("id") != obj->query_temp("bt_ownname") &&
    me->query_temp("bt/working"))
    return notify_fail("你身为捕快，执行公务，可不能杀良冒功！\n");
  if (obj == me) return notify_fail("用 suicide 指令会比较快:P。\n");
  if ((int)obj->query("age") <= 15 && userp(obj))
    return notify_fail("为了世界更美好，放过小孩子吧.\n");

  //限制大米pk  
  if (userp(obj) && obj->query_temp("noliving") &&
    obj->query("id") != me->query("last_die_by_id") &&
    (!objectp(hitter) || hitter->query("id") != me->query("id")) &&
    me->query("combat_exp", 1) < 1000000)
    return notify_fail("想占这样的便宜，多练练再来吧!\n");
  if (userp(me) && userp(obj) && me->query("combat_exp") < 100000 &&
    obj->query("id") != me->query("last_die_by_id") &&
    obj->query("combat_exp") > 1000000)
    return notify_fail("就凭你这点实力，还是少惹点事吧。");

  notify_fail("此人来头不小，还是少惹为妙。\n");
  if (!userp(obj) && !obj->accept_kill(me)) return 0;

  callname = RANK_D->query_rude(obj);
  if (random(3) > 1)
    message_vision("\n$N对着$n喝道：「" + callname + "！今日不是你死就是我活！」\n\n", me, obj);
  else
    message_vision("\n$N对着$n喝道：「" + callname + "！明年今日就是你的忌日！」\n\n", me, obj);

  me->delete("env/combatd");
  obj->delete("env/combatd");

  "/adm/daemons/pocketexpansion"->start_bout(me,obj,1);
  me->kill_ob(obj);
  if (userp(obj))
    write_file(
      "/log/nosave/ATTEMP_KILL",
      sprintf("%s   试图杀死   %s on %s\n", me->name(1), obj->name(1), ctime(time()))
    );
  // Look for PKS 
  if (!userp(obj)) {
    if (!obj->query("owner") &&
      stringp(me->query("family/family_name")) &&
      (string)obj->query("family/family_name") == (string)me->query("family/family_name")) {
      if (living(obj) && !obj->query_temp("noliving"))
        message_vision(HIC "$n厉声对$N道：你我本同门，却为何想相害于我！\n" NOR, me, obj);
      me->delete("family/fealty");
      "/cmds/skill/expell"->main(obj, me->query("id"));
    }
    obj->kill_ob(me);
  } else {
    obj->fight_ob(me);
    tell_object(obj, HIR "如果你要和" + me->name() + "性命相搏，请你也对这个人下一次 kill 指令。\n" NOR);
  }

  return 1;
}
int help(object me) {
  write(@HELP
指令格式 : kill <人物>

    这个指令让你主动开始攻击一个人物，并且试图杀死对方，kill 和 fight 
最大的不同在于双方将会真刀实枪地打斗，也就是说，会真的受伤。由于 kill 
只需单方面一厢情愿就可以成立，因此你对任何人使用 kill 指令都会开始战斗，
通常如果对方是 NPC 的话，他们也会同样对你使用 kill。

    当有人对你使用 kill 指令时会出现红色的字样警告你，对于一个玩家而言，
如果你没有对一名敌人使用过 kill 指令，就不会将对方真的打伤或杀死（使用
毒术除外）。

其他相关指令: hit, fight

HELP
  );
  return 1;
}

cmds/std/fight.lpc:
// fight.c
inherit F_CLEAN_UP;

#include <ansi.h>



int main(object me, string arg) {
  object obj, old_target;
  int recommendation;

  if (me->is_busy())
    return notify_fail("你上一个动作还没有完成！\n");
  if (environment(me)->query("no_ansuan"))
    return notify_fail("这里禁止战斗。\n");
  if (environment(me)->query("no_fight"))
    return notify_fail("这里禁止战斗。\n");
  if (!arg || !objectp(obj = present(arg, environment(me))))
    return notify_fail("你想攻击谁？\n");
  if (!obj->is_character())
    return notify_fail("看清楚一点，那并不是生物。\n");
  if (obj->is_fighting(me))
    return notify_fail("加油！加油！加油！\n");
  if (!living(obj) || obj->query_temp("noliving"))
    return notify_fail(obj->name() + "已经无法战斗了。\n");
  if (obj == me) return notify_fail("你不能攻击自己。\n");

  if (userp(obj) && (object)obj->query_temp("pending/fight") != me) {
    message_vision(
      "\n$N对着$n说道：" + RANK_D->query_self(me) + me->name() + "，领教" + RANK_D->query_respect(obj) + "的高招！\n",
      me,
      obj
    );
    if (objectp(old_target = me->query_temp("pending/fight")))
      tell_object(old_target, YEL + me->name() + "取消了和你比试的念头。\n" NOR);
    me->set_temp("pending/fight", obj);
    tell_object(
      obj,
      YEL "如果你愿意和对方进行比试，请你也对" + me->name() + "(" + (string)me->query("id") + ")" + "下一次 fight 指令。\n" NOR
    );
    write(YEL "由于对方是由玩家控制的人物，你必须等对方同意才能进行比试。\n" NOR);
    return 1;
  }
  if (userp(obj)) {
    me->fight_ob(obj);
    obj->fight_ob(me);
    return 1;
  }
  if (me->is_fighting() || obj->is_fighting())
    return notify_fail("请等双方结束当前战斗，再开始友好切磋。\n");
  if (obj->is_ghost()) return notify_fail("无法与魂魄切磋。\n");
  if (me->is_killing(obj->query("id")) || obj->is_killing(me->query("id")))
    return notify_fail("双方仍有生死敌意，请先结束追杀，再切磋。\n");
  recommendation=me->query_temp("fight_ok") && me->query("family/family_name")=="全真教";
  me->delete_temp("pocket_spar_counted");
  me->delete_temp("pocket_spar_lost_to");obj->delete_temp("pocket_spar_lost_to");
  // Retain original quest setup when accepted; refusal no longer blocks practice.
  if (obj->query("can_speak")) obj->accept_fight(me);
  if (!objectp(obj) || environment(obj)!=environment(me))
    return notify_fail("对方已经离开，无法开始切磋。\n");
  if ((obj->is_fighting() && !obj->is_fighting(me)) ||
      (me->is_fighting() && !me->is_fighting(obj)) ||
      obj->is_killing(me->query("id")) || me->is_killing(obj->query("id")))
    return notify_fail("对方正在处理其他交战，请稍后再试。\n");
  if(recommendation) {
    obj->set("qi",obj->query("eff_qi"));obj->set("jing",obj->query("eff_jing"));
  }
  "/adm/daemons/pocketexpansion"->start_bout(me,obj,1);
  me->set_temp("pocket_sparring",obj);
  obj->set_temp("pocket_sparring",me);
  me->fight_ob(obj);
  obj->fight_ob(me);
  if(recommendation) me->set("pocket_faction_task",(["stage":"challenge","teacher":base_name(obj),"teacher_name":obj->name(),"room":base_name(environment(obj)),"message":"推荐挑战进行中：战胜现任师父后等候推荐信"]));
  "/adm/daemons/pocketui"->watch_sparring(me,obj,recommendation);
  message_vision("$N与$n约定友好切磋，点到为止，气血降至一半即停手。\n",me,obj);

  return 1;
}
int help(object me) {
  write(@HELP
指令格式 : fight <人物>

    这个指令让你向一个人物“讨教”或者是“切磋武艺”，这种形式的战斗
纯粹是点到为止，直到有一方的气降低到一半为止，因此只会消耗体力，不会
真的受伤，但是并不是所有的ＮＰＣ都喜欢打架，因此有许多状况下你的比武
要求会被拒绝。如果对方不愿意接受你的挑战，你仍然可以强行用ｈｉｔ或者
ｋｉｌｌ等等指令开始战斗（甚至ｓｔｅａｌ指令，如果行窃失败也会导致战
斗）。要注意的是动物，因为不通人言，所以它们会对任何攻击施以死亡性报
复，而且许多动物是攻击性的，会见人就杀。

其他相关指令: kill, hit

    如果对方不愿意接受你的挑战，你仍然可以直接用 kill 指令开始战斗。
HELP
  );
  return 1;
}

