#define ONE_DAY                 (86400 / 365)
int pocket_commission(object me,string kind,int issue){string issuer=me->query("quest/"+kind+"/issuer");mapping q=me->query("quest/"+kind);if(stringp(issuer)&&issuer!=base_name(this_object())&&mapp(q)&&!q["finished"]&&(!issue||q["time"]>time())){tell_object(me,"请先向原委托人完成或取消同类任务。\n");return 0;}if(!issue&&!stringp(issuer)&&me->query("family/family_name")!=this_object()->query("family/family_name")){tell_object(me,"旧任务未记录委托人，请找原委托人或重新领取。\n");return 0;}return 1;}
void pocket_credit(object me,object master,string field,int amount){if(me->query("family/family_name")==master->query("family/family_name"))me->add("family/"+field,amount);else me->add("pocket_public_credit/"+replace_string(base_name(master),"/","_")+"/"+field,amount);}
int is_manager() { return 1; }
///////开始秘籍任务
int party_quest_book(object me) {
  object book, room, master = this_object();
  string *dir, *file;
  int i, j;

  me = this_player();
  if(!pocket_commission(me,"book",1))return 1;
  if (0) {
    message_vision(
      "$N对着$n说：这位" + RANK_D->query_respect(me) + "何不加入我" + master->query("family/family_name") + "？\n",
      master,
      me
    );
    return 1;
  }
  if (0) {
    message_vision("$N对着$n说：我不是你的掌门人，你回你们" + me->query("family/family_name") + "去吧。\n", master, me);
    return 1;
  }

  // Modified by zeratul 2000-12-24
  if (me->query("combat_exp") <= 1000) {
    message_vision(WHT "$N对着$n说：你学艺未精，不宜下山。\n" NOR, master, me);
    return 1;
  }

  if (me->query("quest/book") && !me->query("quest/book/finished")) {
    if (time() < (int)me->query("quest/book/time")) {
      message_vision("$N对着$n说：我不是叫你去取" + me->query("quest/book/book") + "，怎么空手回来了！？\n", master, me);
      return 1;
    } else {
      message_vision(CYN "$N对着$n说：你跑到哪里闲逛去了？这次可要小心在意些！\n" CYN, master, me);
      quest_failed(me, "book");
    }
  }

  dir = get_dir("/d/");
  i = random(sizeof(dir));
  file = get_dir("/d/" + dir[i] + "/");
  j = random(sizeof(file));
  if (
    sizeof(file[j]) < 4 ||
    file[j][sizeof(file[j]) - 4..sizeof(file[j]) - 1] != ".lpc" ||
    dir[i] == "gaibang" ||
    dir[i] == "gaochang" ||
    dir[i] == "gumu" ||
    dir[i] == "taohua" ||
    dir[i] == "heizhao" ||
    dir[i] == "shenlong" ||
    dir[i] == "wanjiegu" ||
    dir[i] == "yanziwu" ||
    dir[i] == "death" ||
    dir[i] == "wizard" ||
    dir[i] == "working" ||
    dir[i] == "binghuo" ||
    dir[i] == "xiakedao" ||
    dir[i] == "npc") {
    message_vision("$N对着$n说：本门秘籍？不是好好的么？\n", master, me);
    return 1;
  }
  if (!(room = find_object("/d/" + dir[i] + "/" + file[j])))
    room = load_object("/d/" + dir[i] + "/" + file[j]);
  if (room->query_max_encumbrance() < 10000000
    || !mapp(room->query("exits"))  //add by qingyun
    || room->query("no_quest")  //add by qingyun
  ) {
    message_vision("$N对着$n说：等等吧，等我回头清点一下看看。\n", master, me);
    return 1;
  }
  book = new("/clone/quest/questbook");
  book->set("name", master->query("family/family_name") + "秘籍");
  book->set("owner", me->query("id"));
  book->move(room);
  command("qst " + book->query("name") + "在" + room->query("short") + "(/d/" + dir[i] + "/" + file[j] + ")。\n");

  message_vision("$N对着$n说：本门秘籍流落江湖，听说最近在" + to_chinese(dir[i]) + "一带出现。你去把它取回来吧？\n", master, me);
  me->set("quest/book/book", book->query("name"));
  me->set("quest/book/family", master->query("family/family_name"));
  me->set("quest/book/issuer",base_name(master));
  me->set("quest/book/time", time() + 500);
  me->set("quest/book/dest", to_chinese(dir[i]));
  me->set("quest/book/room",base_name(room));
  me->delete("quest/book/finished");
  return 1;
}
int accept_quest_book(object me, object obj) {
  object master = this_object();
  int num, times, e_bonus, p_bonus, s_bonus;
  int cost;

  me = this_player();
  if(!stringp(me->query("quest/book/book"))||strsrch(obj->query("name"),me->query("quest/book/book"))<0)return 0;
  if(!pocket_commission(me,"book",0))return 1;
  if (0) {
    message_vision("$N对着$n说：我不是你的掌门人，你回你们" + me->query("family/family_name") + "去吧。\n", master, me);
    return 1;
  }
  if (obj->query("owner") != me->query("id")) {
    message_vision("$N对着$n说：这不是我要你找的书。\n", master, me);
    return 1;
  }
  if (!me->query("quest/book") || me->query("quest/book/finished")) {
    message_vision("$N对着$n说：我没要这书，你去哪里拿来的！\n", master, me);
    destruct(obj);
    return 1;
  }
  if (time() - (int)me->query("quest/book/time") > 1500) {
    message_vision("$N对着$n说：你平时练功勤奋点，就不必去这么久了！下次努力点！\n", master, me);
    destruct(obj);
    quest_failed(me, "book");
    return 1;
  }
  destruct(obj);

  num = (int)me->query("perform/number") + 1;
  if (num < 4) times = num;
  else times = 4;

  e_bonus = 100 + random(50);
  cost = time() - ((int)me->query("quest/book/time") - 500);  //花了多少时间完成

  e_bonus += e_bonus * cost / 250;  // cost 最高1500  也就是四倍
  p_bonus = 12 + random(e_bonus / 8);
  s_bonus = random(10) + 10 * times;

  me->add("combat_exp", e_bonus);
  me->add("potential", p_bonus);
  pocket_credit(me,master,"fealty",s_bonus);
  me->set_temp("prize_reason", "秘籍");
  me->set_temp("can_give_prize", 1);
  me->set_temp("prize_exp", e_bonus);
  me->set_temp("prize_pot", p_bonus);
  pocket_credit(me,master,"gongxian",1);


  message_vision("$N对着$n说：本门秘籍？不错，你为本门立了一大功！\n", master, me);
  tell_object(
    me,
    HIW + "你这次行走江湖，获得了" + chinese_number(e_bonus) + "点实战经验，" + chinese_number(p_bonus) + "点潜能，增长了" + chinese_number(s_bonus) + "点师门忠诚。\n" NOR
  );

  quest_finished(me, "book");
  return 1;
}
