string query_save_file() {
  string str = query("save_file");


  if (str) return str;
  str = DATA_DIR + "zhangmen/" + query("current_master");
  //	for (i = 0; i < sizeof(str); i++) if (str[i]==' ') str[i] = '_';
  str = replace_string(str, " ", "_");
  return str;
