        case "刺伤": msg += "刺死了"; msg1 += "刺死了"; break;
        case "瘀伤": msg += "击死了"; msg1 += "击死了"; break;
        case "内伤": msg += "震死了"; msg1 += "震死了"; break;
        default: msg += "杀死了"; msg1 += "杀死了";
      }
    }
    victim->set("last_die_msg", msg);
    victim->set("last_die_by_name", killer->name());
    victim->set("last_die_by_id", killer->query("id"));
    if (victim->query("max_nuqi"))
      victim->set("nuqi", victim->query("max_nuqi"));
    victim->delete_temp("die_reason");
    CHANNEL_D->do_channel(this_object(), "rumor",
      sprintf("我看到%s" + msg1 + "。真是好惨。", victim->name(1)));
    write_file(
      "/log/nosave/KILLRECORD",
      sprintf(
        "%s (%s) 杀死了 %s (%s) on %s\n",
        killer->name(1),
        killer->query("id"),
        victim->name(1),
        victim->query("id"),
        ctime(time())
      )
    );
  } else {
    killer->add("MKS", 1);
    bls = 1;
  }
  if (victim->query("id") == killer->query("last_die_by_id")) {
    tell_object(killer, sprintf("你历尽千辛万苦，终于杀死了%s，报了血海深仇。\n", victim->name(1)));
    killer->set("nuqi", 0);
    tell_object(killer, "你心中的怒气渐渐平息了下来。\n");
    killer->delete("last_die_by_id");
    killer->delete("last_die_by_name");
    killer->delete("last_die_msg");
    victim->set("last_die_msg", sprintf("%s报仇雪恨，杀死了你", killer->name(1)));
    if (victim->query("nuqi"))
      victim->set("nuqi", victim->query("nuqi") / 2);
  }
  if (objectp(weapon = killer->query_temp("weapon")) &&
    weapon->query("ownmake") && weapon->query("owner") == killer->query("id"))
    killer->add("weapon/killed", 1);
  if ((userp(killer) || killer->query("is_baby")) && killer->query("combat_exp") < victim->query("combat_exp"))
    killer->add("shen", -(int)victim->query("shen") / 10);

  if (stringp(vmark = victim->query("vendetta_mark")))
    killer->add("vendetta/" + vmark, 1);

  // 德望因杀人而改变 德望 -= WKS + IKS * 4 + IOKS * 8 + BKS * 2 + BOKS * 4
  if (!victim->query("family") && victim->query("race") == "人类") {
    killer->add("WKS", 1);  // 滥杀无辜百姓哦
    if (victim->query("age") < 17)
      killer->add("WKS1", 1);  // 滥杀儿童
  }
  if (killer->query("family") &&
    killer->query("family/family_name") ==
    victim->query("family/family_name")) {
    killer->add("IKS", 1);  // 门派内讧次数累加 internal conflict
    if (killer->query("family/generation") >
      victim->query("family/generation"))
      killer->add("IKS1", 1);  // 犯上次数累加

  }
  if (killer->query("party") &&
    killer->query("party/party_name") ==
    victim->query("party/party_name")) {
    killer->add("BKS", 1);  // 帮会内讧次数累加
    if (killer->query("party/level") <
      victim->query("party/level"))
      killer->add("BKS1", 1);  // 犯上次数累加
  }
  // 下面是杀人任务
  if (userp(victim) || victim->query("race") != "人类") return;
  if (interactive(killer)) {
    if ((quest = killer->query("quest/shan")) &&
      (int)killer->query("quest/shan/time") >= time() &&
      (!killer->query("quest/shan/lock")) &&
      (!killer->query("quest/shan/finished")) &&
      quest["quest"] == victim->query("name"))
      quest_master = "shan";

    if ((quest_master == "") &&
      (quest = killer->query("quest/helian")) &&
      (int)killer->query("quest/helian/time") >= time() &&
      (!killer->query("quest/helian/lock")) &&
      (!killer->query("quest/helian/finished")) &&
      quest["quest"] == victim->query("name"))
      quest_master = "helian";

    if (quest_master == "") return;

    tell_object(killer, "恭喜你！你又完成了一项任务！\n");
    exp = quest["exp_bonus"] / 2 + random(quest["exp_bonus"] / 2);
    pot = quest["pot_bonus"] / 2 + random(quest["pot_bonus"] / 2);
    score = quest["score"] / 2 + random(quest["score"] / 2);
    exp = exp * 10 / 8;
    pot = pot * 10 / 8;
    score = score * 10 / 8;
    factor = victim->query("quest/" + quest_master + "/factor");
    if (factor) {
      exp = exp * factor / 10;
      pot = pot * factor / 10;
      score = score * factor / 10;
    }
    bonus = (int)killer->query("combat_exp");
    bonus += exp;
    killer->set("combat_exp", bonus);
    killer->set_temp("can_give_prize", 1);
    killer->set_temp("prize_exp", exp);
    killer->set_temp("prize_pot", pot);
    killer->set_temp("prize_reason", "杀人");
    bonus = (int)killer->query("potential");
    bonus = bonus - (int)killer->query("learned_points");
    bonus = bonus + pot;
    //		if( bonus > 300) bonus = 300;
    bonus += (int)killer->query("learned_points");
    killer->set("potential", bonus);
    bonus = (int)killer->query("score");
    bonus += score;
    killer->set("score", bonus);

    killer->add("shen", -(int)victim->query("shen") / 30);
    /*
		bonus = (int)killer->query("shen");
		if(bonus >= 0)
			bonus += score;
		else
			bonus -= score;
		killer->set("shen", bonus);
*/
    tell_object(
      killer,
      HIW "经过你的努力拼杀，你增长了" + chinese_number(exp) + "点实战经验，" + chinese_number(pot) + "点潜能和" + chinese_number(score) + "点江湖阅历。\n" NOR
    );
    quest_finished(killer, quest_master);
  }
}

feature/skill.lpc:
// skill.c
// From ES2
// Modified by Xiang for XKX (12/15/95)

#include <ansi.h>
#include <dbase.h>

mapping skills;
mapping learned;
mapping skill_map;
mapping skill_prepare;

mapping query_skills() { return skills; }
mapping query_learned() { return learned; }

void set_skill(string skill, int val) {
  if (!find_object(SKILL_D(skill))
    && file_size(SKILL_D(skill) + ".lpc") < 0)
    error("F_SKILL: No such skill (" + skill + ")\n");

  if (!mapp(skills)) skills = ([ skill: val ]);
  else skills[skill] = val;
}

int delete_skill(string skill) {
  if (mapp(skills)) {
    map_delete(skills, skill);
    if (mapp(learned)) {
      map_delete(learned, skill);
      return undefinedp(learned[skill]);
    }
    return undefinedp(skills[skill]);
  }
  return 0;
}

// This function 'map' a skill <skill> to another skill <mapped_to>.
// If 2nd argument not given, cancel the mapped skill <skill>.
varargs void map_skill(string skill, string mapped_to) {
  if (!mapped_to && mapp(skill_map)) {
    map_delete(skill_map, skill);
    return;
  }

  if (!find_object(SKILL_D(skill))
    && file_size(SKILL_D(skill) + ".lpc") < 0)
    error("F_SKILL: No such skill (" + skill + ")\n");

  if (!mapp(skills) || undefinedp(skills[mapped_to]))
    return;

  if (!mapp(skill_map)) skill_map = ([ skill: mapped_to ]);
  else skill_map[skill] = mapped_to;
}

// This function 'prepare' a skill <skill> to another skill <mapped_to>.
// If 2nd argument not given, cancel the prepared skill <skill>.
varargs void prepare_skill(string skill, string mapped_to) {
  if (!mapped_to && mapp(skill_prepare)) {
    map_delete(skill_prepare, skill);
    return;
  }

  if (!find_object(SKILL_D(skill))
    && file_size(SKILL_D(skill) + ".lpc") < 0)
    error("F_SKILL: No such skill (" + skill + ")\n");

  if (!mapp(skills) || undefinedp(skills[mapped_to]))
    return;

  if (!mapp(skill_prepare)) skill_prepare = ([ skill: mapped_to ]);
  else skill_prepare[skill] = mapped_to;
}

string query_skill_mapped(string skill) {
  if (mapp(skill_map) && !undefinedp(skill_map[skill]))
    return skill_map[skill];
  return 0;
}

string query_skill_prepared(string skill) {
  if (mapp(skill_prepare) && !undefinedp(skill_prepare[skill]))
    return skill_prepare[skill];
  return 0;
}

varargs int query_skill(string skill, int raw) {
  if (!raw) {
    int s;

    s = query_temp("apply/" + skill);
    if (mapp(skills)) {
      s += skills[skill] / 2;
      if (mapp(skill_map))
        s += skills[skill_map[skill]];
    }
    return s;
  }
  if (mapp(skills) && !undefinedp(skills[skill])) return skills[skill];
  return 0;
}

mapping query_skill_map() {
  return skill_map;
}

mapping query_skill_prepare() {
  return skill_prepare;
}

int skill_death_penalty() {
  string *sk;
  int i;

  if (wizardp(this_object()) || !mapp(skills)) return 0;

  sk = keys(skills);
  /*
	if( !mapp(learned) )
		for(i = 0; i<sizeof(sk); i++)
		{
			skills[sk[i]]--;
			if( skills[sk[i]]<0 ) map_delete(skills, sk[i]);
		}
	else
		for(i = 0; i<sizeof(sk); i++)
		{
//			if( (int)learned[sk[i]] > (skills[sk[i]]+1) * (skills[sk[i]]+1) / 2 )
//				map_delete(learned, sk[i]);
//			else {
//				skills[sk[i]]--;
//				if( skills[sk[i]]<0 ) map_delete(skills, sk[i]);
//			}
			skills[sk[i]]--;
			map_delete(learned,sk[i]);
			if( skills[sk[i]]<0 ) map_delete(skills, sk[i]);
		}
*/
  for (i = 0; i < sizeof(sk); i++) {
    skills[sk[i]]--;
    if (skills[sk[i]] < 0
      || (skills[sk[i]] == 0 && learned[sk[i]] == 0)) {
      map_delete(skills, sk[i]);
      if (mapp(learned))
        map_delete(learned, sk[i]);
    }
  }

  skill_map = 0;
  return 1;
}

int skillreincarnate() {
  string *sk;
  int i;

  sk = keys(skills);
  for (i = 0; i < sizeof(sk); i++) {
    skills[sk[i]]++;
  }
  log_file(
    "skill_re",
    sprintf(
      "[%s] %s eat %s \n",
      ctime(time()),
      geteuid(this_object()),
      base_name(previous_object())
    )
  );
  return 1;
}
varargs void improve_skill(string skill, int amount, int weak_mode) {
  int spi;

  //只有玩家和好学的npc才能学习。比如宠物或玩家小孩等。
  if (!userp(this_object()) && !this_object()->query("curiousness"))
    return;
  if (!find_object(SKILL_D(skill)) &&
    file_size(SKILL_D(skill) + ".lpc") < 0)
    error("F_SKILL: No such skill (" + skill + ")\n");

  if (!weak_mode || !userp(this_object())) {
    if (!mapp(skills)) skills = ([]);
    if (undefinedp(skills[skill])) skills[skill] = 0;
  }

  // Give learning penalty to those learning too much skills.
  spi = this_object()->query_spi();
  if (sizeof(learned) > spi)
    amount /= sizeof(learned) - spi;

  if (!amount) amount = 1;

  if(userp(this_object()) && this_object()->query("pocket_training_boost"))amount*=3;
  if (!mapp(learned)) learned = ([ skill: amount ]);
  else (int)learned[skill] += amount;

  if(userp(this_object()) && this_object()->query("pocket_training_boost") && !weak_mode) {
    int count,ceiling=this_object()->query_temp("pocket_lesson_target");
    while(learned[skill]>(skills[skill]+1)*(skills[skill]+1) && count++<100) {
      if(ceiling && skills[skill]>=ceiling){learned[skill]=0;break;}
      learned[skill]-=(skills[skill]+1)*(skills[skill]+1)+1;skills[skill]++;
      tell_object(this_object(),HIC "你的「"+to_chinese(skill)+"」进步了！\n" NOR);SKILL_D(skill)->skill_improved(this_object());
      if(ceiling && skills[skill]>=ceiling){learned[skill]=0;break;}
    }
  } else {
  if ((!weak_mode || !userp(this_object())) &&
    learned[skill] > (skills[skill] + 1) * (skills[skill] + 1)) {
    skills[skill]++;
    learned[skill] = 0;
    tell_object(this_object(), HIC "你的「" + to_chinese(skill) + "」进步了！\n" NOR);
    SKILL_D(skill)->skill_improved(this_object());
  }
  }
  if(userp(this_object()))"/adm/daemons/pocketgrowth"->sync(this_object());
}

feature/damage.lpc:
// damage.c
// Last Modified by Sir on 2004.1.13  华山论剑不死
#include <ansi.h>
#include <dbase.h>
#include <login.h>
#include <move.h>

#define ENTRY_ROOM      "/d/huashan/sheshen"
int ghost = 0;
int is_ghost() { return ghost; }
void set_ghost(int i) { ghost = i; }

// Friendly practice cannot inflict wounds or knock either partner out.
int pocket_friendly_hit(mixed reason) {
  object partner=query_temp("pocket_sparring");
  if(!objectp(partner) || (objectp(reason) && reason!=partner)) return 0;
  if((query("pocket_arena")||partner->query("pocket_arena"))&&environment(this_object())==environment(partner))return 1;
  return this_object()->is_fighting(partner) && partner->is_fighting(this_object()) &&
    !this_object()->is_killing(partner->query("id")) &&
    !partner->is_killing(this_object()->query("id"));
}

//varargs int receive_damage(string type, int damage, object who)
varargs int receive_damage(string type, int damage, mixed reason) {
  int val;
  int before;
  int imp;

  if (damage < 0) error("F_DAMAGE: 伤害值为负值。\n");
  if (type != "jing" && type != "qi")
    error("F_DAMAGE: 伤害种类错误( 只能是 jing, qi 其中之一 )。\n");

  if(objectp(reason))catch("/adm/daemons/pocketpower"->begin(reason,this_object()));
  before=query(type);
  if (objectp(reason)) set_temp("last_damage_from", reason);
  if (stringp(reason)) set_temp("die_reason", reason);
  if (pocket_friendly_hit(reason)) {
    int floor=query("max_"+type)/2;
    if(floor<1) floor=1;
    if(damage>query(type)-floor) damage=query(type)-floor;
    if(damage<0) damage=0;
  }
  if(!userp(this_object()) && (objectp(query_temp("pocket_coercion"))||query_temp("pocket_coercion_safe_until")>=time())) {
    int floor=query("max_"+type)/10-1;if(floor<1)floor=1;
    if(damage>query(type)-floor)damage=query(type)-floor;if(damage<0)damage=0;
  }
  imp = damage / 5;
  if (query("max_nuqi") && this_object()->is_fighting()) {
    add("nuqi", imp);
    if (query("nuqi") > query("max_nuqi"))
      set("nuqi", query("max_nuqi"));
  }
  val = (int)query(type) - damage;

  if (val >= 0) set(type, val);
  else set(type, -1);

  if(type=="qi" && pocket_friendly_hit(reason) && query("qi")*2<=query("max_qi")) {
    object partner=query_temp("pocket_sparring");
    set_temp("pocket_spar_lost_to",partner);
    if(userp(partner))"/adm/daemons/pocketexpansion"->spar_result(partner,this_object());
    else if(userp(this_object()))"/adm/daemons/pocketexpansion"->spar_result(this_object(),partner);
  }
  if(objectp(reason)) catch("/adm/daemons/pocketpower"->damage_event(reason,this_object(),type,before,query(type),damage,objectp(previous_object())?base_name(previous_object()):""));
  if(!userp(this_object()) && objectp(query_temp("pocket_coercion")) && query("qi")*10<query("max_qi"))
    "/adm/daemons/pocketexpansion"->win_coercion(query_temp("pocket_coercion"),this_object());
  if(userp(this_object()) && objectp(query_temp("pocket_coercion")) && (query("qi")<0||query("jing")<0))call_out("die",0);
  set_heart_beat(1);

  return damage;
}

varargs int receive_wound(string type, int damage, mixed reason) {
  int val;
  int imp;

  if (damage < 0) error("F_DAMAGE: 伤害值为负值。\n");
  if (type != "jing" && type != "qi")
    error("F_DAMAGE: 伤害种类错误( 只能是 jing, qi 其中之一 )。\n");

  if (objectp(reason)) set_temp("last_damage_from", reason);
  if (stringp(reason)) set_temp("die_reason", reason);
  if (pocket_friendly_hit(reason) || (!userp(this_object()) && (objectp(query_temp("pocket_coercion"))||query_temp("pocket_coercion_safe_until")>=time()))) return 0;
  imp = damage / 3;
  if (query("max_nuqi") && this_object()->is_fighting()) {
    add("nuqi", imp);
    if (query("nuqi") > query("max_nuqi"))
      set("nuqi", query("max_nuqi"));
  }
  val = (int)query("eff_" + type) - damage;

  if (val >= 0) set("eff_" + type, val);
  else {
    set("eff_" + type, -1);
    val = -1;
  }

  if ((int)query(type) > val) set(type, val);

  set_heart_beat(1);

  return damage;
}

int receive_heal(string type, int heal) {
  int val,before=query(type);

  if (heal < 0) error("F_DAMAGE: 恢复值为负值。\n");
  if (type != "jing" && type != "qi")
    error("F_DAMAGE: 恢复种类错误( 只能是 jing, qi 其中之一 )。\n");

  val = (int)query(type) + heal;

  if (val > (int)query("eff_" + type)) set(type, (int)query("eff_" + type));
  else set(type, val);

  if(type=="qi" && query(type)>before)catch("/adm/daemons/pocketpower"->heal_event(this_object(),before,query(type),"运功恢复"));
  return heal;
}

int receive_curing(string type, int heal) {
  int max, val;

  if (heal < 0) error("F_DAMAGE: 恢复值为负值。\n");
  if (type != "jing" && type != "qi")
    error("F_DAMAGE: 恢复种类错误( 只能是 jing, qi 其中之一 )。\n");

  val = (int)query("eff_" + type);
  max = (int)query("max_" + type);

  if (val + heal > max) {
    set("eff_" + type, max);
    return max - val;
  } else {
    set("eff_" + type, val + heal);
    return heal;
  }
}

void unconcious() {
  object defeater;
  object riding;

  // 所在房间定义了no_unconcious，不允许晕倒 
  if (environment()->no_unconcious(this_object())) return;
  if (!living(this_object()) || this_object()->query_temp("noliving"))
    return;
  if (wizardp(this_object()) && query("env/immortal")) return;

  if (objectp(defeater = query_temp("last_damage_from"))) {
    COMBAT_D->winner_reward(defeater, this_object());
    if (environment(this_object()) == environment(defeater))
      if (this_object()->query("max_nuqi"))
        this_object()->set("nuqi", query("max_nuqi"));
  }
  this_object()->remove_all_enemy();
  this_object()->set_temp("faint_by", query_temp("last_damage_from"));
  if (objectp(riding = query_temp("is_riding"))) {
    message_vision("$N一头从$n上面栽了下来！\n",
      this_object(), riding);
    delete_temp("is_riding");
    riding->delete_temp("is_rided_by");
    riding->move(environment());
  }

  message("system", HIR "\n你的眼前一黑，接着什么也不知道了....\n\n" NOR, this_object());
  // 避免add_action的bug
  if (userp(this_object()))
    this_object()->set_temp("noliving/unconcious", 1);
  else this_object()->disable_player(" <昏迷不醒>");

  set("jing", 0);
  set("qi", 0);

  set_temp("block_msg/all", 1);
  COMBAT_D->announce(this_object(), "unconcious");

  call_out("revive", random(100 - query("con")) + 30);
}

varargs void revive(int quiet) {
  remove_call_out("revive");
  while (environment()->is_character())
    this_object()->move(environment(environment()));
  // 避免add_action的bug
  if (userp(this_object())) this_object()->delete_temp("noliving");
  else this_object()->enable_player();

  if (!quiet) {
    COMBAT_D->announce(this_object(), "revive");
    set_temp("block_msg/all", 0);
    message("system", HIY "\n慢慢地你终于又有了知觉....\n\n" NOR, this_object());
  } else
    set_temp("block_msg/all", 0);
}

void die() {
  object corpse, killer;

  string reason;
  object riding;


  if (!living(this_object()) || this_object()->query_temp("noliving"))
    revive(1);
  else delete_temp("faint_by");
  // 所在房间定义了no_die，不允许死亡 
  if (environment()->no_die(this_object())) return;
  if (wizardp(this_object()) && query("env/immortal")) return;

  if (userp(this_object()) && this_object()->is_ghost()) {
    this_object()->receive_curing("jing", 10);
    this_object()->receive_curing("qi", 10);
    message_vision(HIW "黑白索魂无常忽然出现，喝道：何方孤魂野鬼，快快随我前去阎罗大殿！\n" NOR, this_object());
    this_object()->move("/d/death/dadian");
    return;
  }


  // 擂台比武不死
  if (file_name(environment(this_object())) == "/d/city/leitai") {
    message_vision(HIR "公平子道：“已分胜负，不决生死。”\n" NOR, this_object());
    this_object()->move("/d/city/wudao4");
    this_object()->receive_curing("jing", 10);
    this_object()->receive_curing("qi", 10);
    return;
  }
  if (userp(this_object()) && environment(this_object())->query("bwdhpk")) {
    message_vision(HIR "华山论剑，只分胜负，不决生死！。\n" NOR, this_object());
    message_vision(HIR "$N被抬了下去。\n" NOR, this_object());
    if (objectp(killer = query_temp("last_damage_from"))) {
      killer->add_temp("bwdh_pknum", 1);
      message(
        "channel:chat",
        HIC "【华山论剑】公平子：" + this_object()->query("name") + "不敌" + killer->query("name") + "，被迫退出华山论剑！\n" NOR,
        users()
      );
    }
    this_object()->set("eff_jing", (int)this_object()->query("max_jing"));
    this_object()->set("jing", (int)this_object()->query("max_jing"));
    this_object()->set("eff_qi", (int)this_object()->query("max_qi"));
    this_object()->set("qi", (int)this_object()->query("max_qi"));
    this_object()->set("jingli", (int)this_object()->query("max_jingli"));
    this_object()->set("neili", (int)this_object()->query("max_neili"));
    this_object()->remove_all_killer();
    this_object()->remove_all_enemy();
    this_object()->delete_temp("bwdh_join");
    this_object()->delete_temp("bwdh_pknum");
    this_object()->delete_temp("bwdh_nknum");
    this_object()->move(ENTRY_ROOM);
    return;
  }
  if (objectp(riding = query_temp("is_riding"))) {
    message_vision("$N一头从$n上面栽了下来！\n",
      this_object(), riding);
    delete_temp("is_riding");
    riding->delete_temp("is_rided_by");
    riding->move(environment());
  }


  if (this_object()->query_condition("huaiyun") > 0 &&
    this_object()->query_condition("huaiyun") < 2560)
    tell_object(this_object(), "你莫名地感到一阵心痛。。。\n");
  if (objectp(killer = query_temp("last_damage_from")) &&
    file_name(environment(killer)) == file_name(environment(this_object()))) {
    // Clear all the conditions by normal death.
    if (userp(this_object()) && userp(killer) && (!environment(this_object())->query("bwdhpk")) &&
      (time() - this_object()->query("dietime") < 13400 ||
        time() - killer->query("killertime") < 13400)) {
      this_object()->set("eff_qi", 10);
      this_object()->set("eff_jing", 10);
      this_object()->set("qi", 10);
      this_object()->set("jing", 10);
      message_vision(HIY "\n天后仙子" HIC "自云中飘然而下：" HIR "一日不过四。不准频繁屠杀！\n" NOR, this_object());
      message_vision(HIG "挥起长袖，摆起一阵香风把" + this_object()->name() + "刮回武庙。\n" NOR, this_object());
      this_object()->move("/d/city/wumiao");
      this_object()->start_busy(10);
      return;
    }
    this_object()->clear_condition();
    this_object()->set("dietime", time());
    this_object()->add("normal_die", 1);
    /* 杀手本次杀人时间 */
    if (userp(this_object()))
      killer->set("killertime", time());
    set_temp("my_killer", killer->query("id"));
    COMBAT_D->killer_reward(killer, this_object());
  } else if (userp(this_object())) {
    this_object()->set("last_die_msg", "死得很离奇");
    if (stringp(reason = this_object()->query_temp("die_reason")))
      this_object()->set("last_die_msg", reason);
    else if (stringp(reason = this_object()->query_temp("last_damage_from")))
      this_object()->set("last_die_msg", reason + "死了");
    message(
      "channel:rumor",
      HIM "【谣言】" + "听说" + this_object()->name() + HIM "死了，而且死得很离奇。\n" NOR,
      users()
    );

    this_object()->delete("last_die_by_name");
    this_object()->delete("last_die_by_id");
    this_object()->delete_temp("die_reason");
    this_object()->delete_temp("last_damage_from");
    this_object()->add("dietimes", 1);
  }
  COMBAT_D->announce(this_object(), "dead");
  if (objectp(this_player()) && this_player()->query_condition("huaiyun"))
    this_object()->clear_condition("huaiyun");
  if(objectp(killer)&&userp(killer)&&!query_temp("pocket_kill_counted")) {killer->add("pocket_stats/kills",1);"/adm/daemons/pocketexpansion"->reward(killer,this_object(),"杀敌");set_temp("pocket_kill_counted",1);}
  if (objectp(corpse = CHAR_D->make_corpse(this_object(), killer))) {
    corpse->move(environment());
    // 超度用的经验值
    corpse->set("combat_exp", this_object()->query("combat_exp"));
    // 死者是玩家
    if (userp(this_object()))
      corpse->set("userp", 1);
    else {
      // 死者是任务对象
      if (this_object()->query("quest"))
        corpse->set("quest", this_object()->query("quest"));
      if (this_object()->query("owner"))
        corpse->set("owner", this_object()->query("owner"));
    }
  }

  this_object()->remove_all_killer();
  all_inventory(environment())->remove_killer(this_object());

  this_object()->dismiss_team();
  if (userp(this_object())) {
    //		if (this_object()->is_busy())
    //			this_object()->interrupt_me();
    this_object()->remove_busy();
    set("jing", 1); set("eff_jing", 1);
    set("qi", 1); set("eff_qi", 1);
    ghost = 1;
    this_object()->move(DEATH_ROOM);
    DEATH_ROOM->start_death(this_object());
  } else {
    "/adm/daemons/pocketui"->schedule_npc_return(this_object());
    //浩劫系统的触发条件
    LOGIN_D->add_dienpc();
    destruct(this_object());
  }
}

int max_food_capacity() { return query_weight() / 200; }

int max_water_capacity() { return query_weight() / 200; }

void reincarnate() {
  ghost = 0;
  set("eff_jing", query("max_jing"));
  set("eff_qi", query("max_qi"));
  set("food", max_food_capacity());
  set("water", max_water_capacity());
}

// Carry fractional points so small gains still total exactly one fifth.
int pocket_natural_gain(string resource,int amount) {
  int total;
  if(!this_object()->is_fighting())return amount;
  total=amount+this_object()->query_temp("pocket_natural_remainder/"+resource);
  this_object()->set_temp("pocket_natural_remainder/"+resource,total%5);
  return total/5;
}

int heal_up() {
  int update_flag, qi_before;
  mapping my;

  //	if( this_object()->is_fighting() ) return -1;

  update_flag = 0;

  my = query_entire_dbase();
  this_object()->pocket_enforce_locks();



  //就是下面这两句话！！！！！！！！！！！！！
  //就是下面这两句话！！！！！！！！！！！！！
  //就是下面这两句话！！！！！！！！！！！！！
  //就是下面这两句话！！！！！！！！！！！！！


  if (environment(this_object()) && environment(this_object())->is_chat_room()
    && this_object()->query("env/halt_age"))




    return 0;

  if (!my["pocket_water_locked"] && my["water"] > 0) { my["water"] -= 1; update_flag++; }
  if (!my["pocket_food_locked"] && my["food"] > 0) { my["food"] -= 1; update_flag++; }

  if (my["water"] < 1 &&  //人和宠物如果没饮水，不能恢复身体。
  (userp(this_object()) || this_object()->query("ownername")))
    return update_flag;

  if (my["food"] < 1 &&  //人和宠物如果没食物，不能恢复身体。
  (userp(this_object()) || this_object()->query("ownername")))
    return update_flag;

  qi_before=my["qi"];

  my["jing"] += pocket_natural_gain("jing",my["con"] / 3 + my["max_jingli"] / 10);
  if (my["jing"] >= my["eff_jing"]) {
    my["jing"] = my["eff_jing"];
    if (my["eff_jing"] < my["max_jing"]) {
      my["eff_jing"]+=pocket_natural_gain("eff_jing",1); update_flag++;
    }
  } else update_flag++;

  my["qi"] += pocket_natural_gain("qi",my["con"] / 3 + my["max_neili"] / 10);
  if (my["qi"] >= my["eff_qi"]) {
    my["qi"] = my["eff_qi"];
    if (my["eff_qi"] < my["max_qi"]) {
      my["eff_qi"]+=pocket_natural_gain("eff_qi",1); update_flag++;
    }
  } else update_flag++;

  if (my["max_jingli"] && my["jingli"] < my["max_jingli"]) {
    my["jingli"] += pocket_natural_gain("jingli",(int)this_object()->query_skill("taoism", 1) / 20);
    if (my["jingli"] > my["max_jingli"]) my["jingli"] = my["max_jingli"];
    update_flag++;
  }

  if (my["max_neili"] && my["neili"] < my["max_neili"]) {
    my["neili"] += pocket_natural_gain("neili",(int)this_object()->query_skill(
      "force",
      1
    ) / 2 + (int)this_object()->query("sta") / 3);
    if (my["neili"] > my["max_neili"]) my["neili"] = my["max_neili"];
    update_flag++;
  }

  if (my["max_tili"] && my["tili"] < my["max_tili"]) {
    my["tili"] += pocket_natural_gain("tili",(int)this_object()->query_skill(
      "parry",
      1
    ) / 2 + (int)this_object()->query("sta") / 3);
    if (my["tili"] > my["max_tili"]) my["tili"] = my["max_tili"];
    update_flag++;
  }

  if(my["qi"]>qi_before)catch("/adm/daemons/pocketpower"->heal_event(this_object(),qi_before,my["qi"],"自然恢复（战斗中20%）"));
  this_object()->pocket_enforce_locks();
  return update_flag;
}

feature/dbase.lpc:
// dbase.c

//#include <dbase.h>

inherit F_TREEMAP;

mapping dbase;
nosave mapping tmp_dbase;

//	The default_ob provides the default values of the dbase. It is set to
//	be master copy of an object.
nosave mixed default_ob;

mixed query_default_object() { return default_ob; }
void set_default_object(mixed ob) {
  //	if( geteuid(previous_object()) != ROOT_UID )
  //		error("dbase: Only this_object() or object with root euid can set default_ob.\n");
  if (!geteuid()) seteuid(getuid());
  default_ob = ob;
  ob->add("no_clean_up", 1);
}

// Original recovery and login code also write whole mappings. Normalize locks at
// their boundaries, including derived maximum changes, without granting growth.
void pocket_enforce_locks() {
  int cap;
  if (!mapp(dbase) || !userp(this_object()) || this_object()->is_ghost()) return;
  foreach (string resource in ({"jing","qi"})) if (dbase["pocket_"+resource+"_locked"]) {
    dbase[resource]=dbase["max_"+resource]; dbase["eff_"+resource]=dbase["max_"+resource];
  }
  if (dbase["pocket_food_locked"]) dbase["food"]=this_object()->max_food_capacity();
  if (dbase["pocket_water_locked"]) dbase["water"]=this_object()->max_water_capacity();
  cap=dbase["max_neili"]>0?dbase["max_neili"]:300;
  if (dbase["pocket_neili_locked"]) {
    if (dbase["neili"]<cap) dbase["neili"]=cap;
    if (dbase["neili"]>cap*2) dbase["neili"]=cap*2;
  }
}

mixed set(string prop, mixed data) {
  if (!mapp(dbase)) dbase = ([]);
  // Explicit player-only experience switch. Keep normal costs when unlocked.
  if ((prop == "jing" || prop == "eff_jing") && dbase["pocket_jing_locked"] &&
      userp(this_object()) && !this_object()->is_ghost() && intp(data) &&
      dbase["max_jing"] > 0 && data < dbase["max_jing"])
    data = dbase["max_jing"];

  if (userp(this_object()) && !this_object()->is_ghost() && intp(data)) {
    if ((prop == "qi" || prop == "eff_qi") && dbase["pocket_qi_locked"] &&
        dbase["max_qi"] > 0 && data < dbase["max_qi"])
      data = dbase["max_qi"];
    if (prop == "food" && dbase["pocket_food_locked"]) {
      int cap = this_object()->max_food_capacity();
      if (cap > 0 && data < cap) data = cap;
    }
    if (prop == "water" && dbase["pocket_water_locked"]) {
      int cap = this_object()->max_water_capacity();
      if (cap > 0 && data < cap) data = cap;
    }
    if (prop == "neili" && dbase["pocket_neili_locked"]) {
      int floor = dbase["max_neili"] > 0 ? dbase["max_neili"] : 300;

      if (data < floor) data = floor;
    }
  }

  if (strsrch(prop, '/') != -1)
    return _set(dbase, explode(prop, "/"), data);

  dbase[prop] = data;
  if (prop=="max_qi" || prop=="max_jing" || prop=="max_neili") pocket_enforce_locks();
  return dbase[prop];
}

varargs mixed query(string prop, int raw) {
  mixed data;
  if(prop=="env/wimpy" && !userp(this_object()) && mapp(tmp_dbase) && objectp(tmp_dbase["pocket_coercion"]))return 0;
  if(prop=="env/wimpy" && !userp(this_object()) && mapp(tmp_dbase) && objectp(tmp_dbase["pocket_sparring"])) {
    object partner=tmp_dbase["pocket_sparring"];
    if(this_object()->is_fighting(partner) && partner->is_fighting(this_object()) &&
       !this_object()->is_killing(partner->query("id")) && !partner->is_killing(this_object()->query("id"))) return 0;
  }
  if (!mapp(dbase)) return 0;

  if (undefinedp(dbase[prop]) && (strsrch(prop, '/') != -1))
    data = _query(dbase, explode(prop, "/"));
  else
    data = dbase[prop];

  if (undefinedp(data) && default_ob)
    data = default_ob->query(prop, 1);

  if (raw) return data;

  return evaluate(data, this_object());
}

int delete(string prop) {
  if (!mapp(dbase)) return 0;

  if (strsrch(prop, '/') != -1)
    return _delete(dbase, explode(prop, "/"));
  else {
    map_delete(dbase, prop);
    return 1;
  }
}

mixed add(string prop, mixed data) {
  mixed old;

  if (!mapp(dbase) || !(old = query(prop, 1)))
    return set(prop, data);

  if (functionp(old))
    error("dbase: add() - called on a function type property.\n");

  return set(prop, old + data);
}

mapping query_entire_dbase() {
  //	if( (previous_object() != this_object())
  //	&&	(geteuid(previous_object()) != ROOT_UID) )
  //		error("dbase: query_entire_dbase() - must has root euid or be this_object().\n");

  return dbase;
}

mixed set_temp(string prop, mixed data) {
  if (!mapp(tmp_dbase)) tmp_dbase = ([]);

  if (strsrch(prop, '/') != -1)
    return _set(tmp_dbase, explode(prop, "/"), data);

  return tmp_dbase[prop] = data;
}

varargs mixed query_temp(string prop, int raw) {
  mixed data;

  if (!mapp(tmp_dbase)) return 0;

  if (strsrch(prop, '/') != -1)
    data = _query(tmp_dbase, explode(prop, "/"));
  else
    data = tmp_dbase[prop];

  if (functionp(data) && !raw)
    return (* data) (this_object());
  else
    return data;
}

int delete_temp(string prop) {
  if (!mapp(tmp_dbase)) return 0;

  if (strsrch(prop, '/') != -1)
    return _delete(tmp_dbase, explode(prop, "/"));
  else {
    map_delete(tmp_dbase, prop);
    return 1;
  }
}

mixed add_temp(string prop, mixed data) {
  mixed old;

  if (!mapp(tmp_dbase) || !(old = query_temp(prop, 1)))
    return set_temp(prop, data);

  if (functionp(old))
    error("dbase: add_temp() - called on a function type property.\n");

  return set_temp(prop, old + data);
}

mapping query_entire_temp_dbase() {
  //	if( (previous_object() != this_object())
  //	&&	(geteuid(previous_object()) != ROOT_UID) )
  //		error("dbase: query_entire_temp_dbase() - must has root euid or be this_object().\n");

  return tmp_dbase;
}

feature/alias.lpc:
// alias.c
// From ES2
// Modified for XKX by Xiang (12/15/95)
// Last Modified for XKX100 by Winder (05/17/2001)
// #pragma save_binary

#define MAX_REPEAT 30
#define MAX_ALIASES 40
#define HISTORY_BUFFER_SIZE 10
#define MAX_IN_A_ROW 20
#include <ansi.h>

mapping alias;

nosave string *history, last_input;
nosave int last_cmd, repeat_cnt = 0;
nosave int last_check, maxcom = 0;
nosave int pocket_last_input_at;

string process_input(string str) {
  string *args, cmd, argstr, badstr;
  int i, j;
  object me = this_object();

  /* 限制蹩脚机器人
	if(maxcom == 0) last_check = time();
	if(maxcom == (MAX_IN_A_ROW - 1) && time() == last_check)
	{
		me->start_busy(1);
		return "";
	}
	else
		maxcom++;
	maxcom = maxcom % MAX_IN_A_ROW ;
*/
  // 限制disable_player后遗症
  if (!interactive(me)) command("quit");       // 非交互物品
  if (!query_heart_beat(me)) command("quit");  // 无心跳
  if (!living(me)) return "";                   // 不是活物
  if (me->query_temp("noliving")) return "";   // 非活动玩家
  if (!wizardp(me)) {
    if (me->query("jing") < 0 || me->query("qi") < 0) {
      write("你马上要昏迷了，不能做任何事情。\n");
      return "";
    }
  }
  // 限制粗口
  badstr = lower_case(str);
  badstr = replace_string(badstr, "$blk$", "");
  badstr = replace_string(badstr, "$red$", "");
  badstr = replace_string(badstr, "$grn$", "");
  badstr = replace_string(badstr, "$yel$", "");
  badstr = replace_string(badstr, "$blu$", "");
  badstr = replace_string(badstr, "$mag$", "");
  badstr = replace_string(badstr, "$cyn$", "");
  badstr = replace_string(badstr, "$wht$", "");
  badstr = replace_string(badstr, "$hir$", "");
  badstr = replace_string(badstr, "$hig$", "");
  badstr = replace_string(badstr, "$hiy$", "");
  badstr = replace_string(badstr, "$hib$", "");
  badstr = replace_string(badstr, "$him$", "");
  badstr = replace_string(badstr, "$hic$", "");
  badstr = replace_string(badstr, "$hiw$", "");
  badstr = replace_string(badstr, "$nor$", "");
  badstr = replace_string(badstr, "$blink$", "");

  if (!wizardp(me) && strsrch(badstr, "fuck") >= 0) {
    me->add_temp("fuck", 1);
    if (me->query_temp("fuck") > 1)
      return "";
    message(
      "channel:chat",
      HIC "【闲聊】" + me->name() + "张开大嘴放了个冲天大臭屁，结果一口气没上来，就被自己的大粪给活活憋死了。\n" NOR,
      users()
    );
    return "";
  }
  // 限制非法获取的生命数据
  if (userp(me)) {
    if ((int)me->query("eff_qi") > (int)me->query("max_qi"))
      me->set("eff_qi", me->query("max_qi"));
    if ((int)me->query("qi") > (int)me->query("eff_qi"))
      me->set("qi", me->query("eff_qi"));
    if ((int)me->query("eff_jing") > (int)me->query("max_jing"))
      me->set("eff_jing", me->query("max_jing"));
    if ((int)me->query("jing") > (int)me->query("eff_jing"))
      me->set("jing", me->query("eff_jing"));
    if ((int)me->query("neili") > (int)me->query("max_neili") * 2)
      me->set("neili", (int)me->query("max_neili") * 2);
  }
  // 限制频道字符和其他泥巴宣传
  if (!wizardp(me) && (strsrch(
    str,
    "["
  ) >= 0 || strsrch(
    str,
    "%"
  ) >= 0 || strsrch(
    str,
    "5555"
  ) >= 0 || strsrch(
    str,
    "8888"
  ) >= 0 || strsrch(str, "6666") >= 0 || strsrch(str, "9999") >= 0)) return "";
  // 限制太多的命令输入行
  // This guard used to count identical commands forever. Preserve burst flood
  // protection while allowing paced native training every two seconds.
  if (time()-pocket_last_input_at > 1) repeat_cnt=0;
  pocket_last_input_at=time();
  if (str == last_input && str != "") {
    repeat_cnt++;
    if (repeat_cnt > MAX_REPEAT) {
      tell_object(me, "\n天后仙子突然在一阵烟雾中出现：你重复命令太多，最后那些都失效了！！\n\n");
      //			command("quit");
      if (!me->is_busy()) me->start_busy(random(10));
      return "";
    }
  } else {
    repeat_cnt = 0;
    if (str != "") {
      last_input = str;
    }
  }

  if (str[0] == '!') {
    if (pointerp(history) && sizeof(history)) {
      if (sscanf(str, "!%d", i))
        str = (string)history[(HISTORY_BUFFER_SIZE + last_cmd - i) % HISTORY_BUFFER_SIZE];
      else
        str = history[last_cmd];
    } else
      return "";
  } else {
    if (!pointerp(history)) history = allocate(HISTORY_BUFFER_SIZE);
    last_cmd = (last_cmd + 1) % HISTORY_BUFFER_SIZE;
    history[last_cmd] = str;
  }

  if (mapp(alias)) {
    if (!undefinedp(alias[str]))
      return replace_string(alias[str], "$*", "");

    if (sscanf(str, "%s %s", cmd, argstr) == 2 && !undefinedp(alias[cmd])) {
      cmd = replace_string(alias[cmd], "$*", argstr);
      args = explode(argstr, " ");
      if ((j = sizeof(args)))
        for (i = 0; i < j; i++)
          cmd = replace_string(cmd, "$" + (i + 1), args[i]);
      return cmd;
    }
  }
  return (string)ALIAS_D->process_global_alias(str);
}

int set_alias(string verb, string replace) {
  if (!replace) {
    if (mapp(alias)) map_delete(alias, verb);
    return 1;
  } else {
    if (!mapp(alias)) alias = ([ verb: replace ]);
    else if (sizeof(alias) > MAX_ALIASES)
      return notify_fail("您设定的 alias 太多了，请先删掉一些不常用的。\n");
    else alias[verb] = replace;
    return 1;
  }
}

mapping query_all_alias() {
  return alias;
}

