  add_action("do_hit", "hit");
  add_action("do_kill", "kill");
  add_action("do_give", "give");
  add_action("do_hp", "hp");
  add_action("do_touxi", "touxi");
  remove_call_out("do_check");
  call_out("do_check", A_TIME);
  remove_call_out("do_check1");
  call_out("do_check1", B_TIME);
